def write(name,d):d.to_csv(OUT/name,index=False,quoting=csv.QUOTE_MINIMAL)
def side(p,t):return 'over' if p>=t else 'under'
def favwin(actual,line,fav):return np.nan if pd.isna(actual) or actual==line else bool((actual>line)==(fav=='over'))
def pnl(price,win):return np.nan if pd.isna(win) else (price/100 if price>0 else 100/abs(price)) if win else -1.
def raw_lr(pipe,X):
 z=pipe.named_steps['pre'].transform(X);cc=pipe.named_steps['clf'].calibrated_classifiers_;return float(np.mean([c.estimator.predict_proba(z)[0,1] for c in cc]))
