def family(name):
 n=name.lower()
 if n.startswith('isna__'):return 'data_sufficiency_or_history_depth'
 if any(x in n for x in ('line','price','implied','market','prop_value')):return 'market_or_line_input'
 if any(x in n for x in ('at_bats','plate_appearances','opportunity','outs_recorded','workload')):return 'opportunity_or_workload'
 if n.startswith('d7_') or 'streak' in n:return 'recent_form'
 if n.startswith(('d15_','d30_')):return 'longer_term_form'
 if n.startswith('bvp_') or any(x in n for x in ('opponent','starting_pitcher')):return 'opponent_or_matchup'
 if any(x in n for x in ('team','is_home','time_of_day','game_day','game_type')):return 'team_environment'
 if any(x in n for x in ('source','fallback','payload','provenance')):return 'fallback_or_provenance_indicator'
 if any(x in n for x in ('interaction','per_ab','per_hit','rate','avg','slg')):return 'duplicate_or_shared_parent_family'
 if any(x in n for x in ('hits','bases','home_runs','strikeouts','walks','earned_runs','doubles','rbi')):return 'player_ability_or_performance_rate'
 return 'other_explicit_family'
