 opp=[f.get('avg_ab_per_game_d7'),f.get('d7_at_bats')];ability=f.get(f'd30_{prop}');opportunity_ability='NOT_EVALUABLE'
 if prop=='total_bases' and any(v is not None for v in opp) and ability is not None:opportunity_ability='CONFLICT' if (float(opp[0] or opp[1] or 0)<=0)!=(float(ability)<=line) else 'ALIGNED'
