def origin(row):
 fav=row['market_favorite_side'];seq=[row['underlying_side'],row['embedded_calibration_side'],row['blend_side'],row['line_sensitivity_side']];flips=[i for i in range(1,len(seq)) if seq[i]!=seq[i-1]]
 if seq[-1]==fav:return 'FINAL_AGREEMENT_NOT_OPPOSITION'
 if len(flips)>1:return 'MULTIPLE_STAGE_OPPOSITION'
 if seq[0]!=fav and not flips:return 'FINAL_OPPOSITION_WITHOUT_STAGE_FLIP'
 if seq[0]!=fav:return 'BASE_ESTIMATOR_OPPOSITION'
 if flips==[1]:return 'EMBEDDED_CALIBRATION_CREATED_OPPOSITION'
 if flips==[2]:return 'BLEND_CREATED_OPPOSITION'
 if flips==[3]:return 'LINE_SENSITIVITY_CREATED_OPPOSITION'
 return 'STAGE_ORIGIN_UNRESOLVED'
def characterize(x,label):
 r=x[x.outcome_status.isin(['WIN','LOSS'])].copy();fw=r.favorite_outcome_win.astype(float);fp=r.favorite_price.astype(float);be=len(r)/(len(r)+sum(p/100 if p>0 else 100/abs(p) for p in fp)) if len(r) else np.nan;y=(r.outcome_status=='WIN').astype(float);mp=r.model_selected_side_probability.clip(1e-6,1-1e-6);mk=r.selected_side_no_vig_probability.clip(1e-6,1-1e-6)
 return {'category':label,'rows':len(x),'resolved_rows':len(r),'dates':x.game_date.nunique(),'games':x.game_id.nunique(),'distinct_player_games':x[['game_id','player_id']].drop_duplicates().shape[0],'market_favorite_win_rate':fw.mean(),'market_favorite_roi':np.mean([pnl(p,w) for p,w in zip(fp,fw)]) if len(r) else np.nan,'market_break_even_rate':be,'break_even_shortfall':fw.mean()-be,'model_selected_opposite_side_roi':r.loc[~r.model_market_agreement,'pnl_1u'].mean(),'model_brier':np.mean((mp-y)**2),'model_log_loss':np.mean(-(y*np.log(mp)+(1-y)*np.log(1-mp))),'market_brier':np.mean((mk-y)**2),'market_log_loss':np.mean(-(y*np.log(mk)+(1-y)*np.log(1-mk))),'maximum_date_share':x.game_date.value_counts(normalize=True).max() if len(x) else np.nan,'maximum_proposition_share':x.proposition.value_counts(normalize=True).max() if len(x) else np.nan}
